dish_name = #{dishName}, dish_status = #{dishStatus}, for_sale = #{forSale}, category_id = #{categoryId}, price = #{price}, dish_sales = #{dishSales}, dish_score = #{dishScore}, dish_score_person = #{dishScorePerson}, dish_photo_id = #{dishPhotoId}, dish_photo = #{dishPhoto}, ingredients = #{ingredients},
