mapper.select:
SELECT 
FROM dish

    AND dish_id = #{dishId}
    AND dish_name LIKE CONCAT('%', #{dishName}, '%')
    AND dish_status = #{dishStatus}
    AND for_sale = #{forSale}
    AND category_id = #{categoryId}
    AND shop_id = #{shopId}

AND dish_status != 4
